package com.EOT.project.controller;
import com.EOT.project.dto.request.UserAchievementProgressDTO; import com.EOT.project.service.*; import java.util.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class UserAchievementControllerTest { @Mock UserAchievementService service; @Mock CurrentUserService current; @InjectMocks UserAchievementController controller;
 @Test void checksOwnershipBeforeProgressUpdate() { UUID userId=UUID.randomUUID(); var dto=UserAchievementProgressDTO.builder().userId(userId).achId(UUID.randomUUID()).progress(1).build(); var auth=new UsernamePasswordAuthenticationToken("auth","x"); controller.updateAchievementProgress(dto,auth); verify(current).requireOwnerOrAdmin(auth,userId); verify(service).updateProgress(dto); } }
